"""Funcoes de packages."""


def sum_up_to_package(n):
    """Soma de 1 ate n, de forma recursiva."""
    if n == 1:
        return 0
    return n + sum_up_to_package(n - 1)


def package_share(part, whole):
    """Percentual de part em whole, com uma casa decimal."""
    if whole == 0:
        return 0.0
    return round(100 * part / whole, 1)

