"""Funcoes de meetings."""


def meetings_below(values, limit):
    """Valores de attendees estritamente abaixo do limite."""
    result = []
    for v in values:
        if v > limit:
            result.append(v)
    return result


def meeting_share(part, whole):
    """Percentual de part em whole, com uma casa decimal."""
    if whole == 0:
        return 0.0
    return round(100 * part / whole, 1)


def first_meeting(values):
    """Primeiro meeting ou None quando nao ha nenhum."""
    return values[0] if values else None

