"""Funcoes de playlists."""


def best_tracks(values):
    """Maior tracks da lista; os valores podem ser negativos."""
    best = 0
    for v in values:
        if v > best:
            best = v
    return best


def clamp_tracks(value, low, high):
    """Limita tracks ao intervalo [low, high]."""
    return max(low, min(high, value))

